#ifndef APP_STORE_SHARED_CONTROLLER_H
#define APP_STORE_SHARED_CONTROLLER_H
#include "RiscRuntimeV1.h"
#include "RiscRealtimeV1.h"
#include "SoftwareUpdateV1.h"
#include "PortableWifiSavedNetwork.h"
#include "PortableRadioPolicy.h"
#include <stddef.h>
#include <stdio.h>
#include <string.h>
typedef struct {void *context;bool(*alive)(void*);void(*retain)(void*);bool(*pause)(void*);bool(*network_needed)(void*);bool(*network_ready)(void*,uint64_t);} app_store_hooks;
typedef struct {
 const risc_runtime_api_v1 *runtime;app_store_hooks hooks;
 risc_runtime_capability_v1 service_grant,wifi_grant,storage_grant,clock_grant;
 const software_update_v1 *release,*service;const wifi_api_v1 *wifi;const risc_key_value_v1 *storage;const risc_realtime_api_v1 *clock;
 software_update_status_v1 status;software_update_row_v1 selected_row;
 unsigned selected,page;bool confirming,connecting,radio_owned,cleanup_pending,restart_pending,install_after_connect,network_continuation,network_wait,terminal,opened,dirty;
 uint32_t connect_started;char message[128];
} app_store_controller;
static bool asc_live(app_store_controller*s){if(s->terminal)return false;if(!s->runtime||risc_runtime_get_api(1)!=s->runtime||(s->hooks.alive&&!s->hooks.alive(s->hooks.context))){s->terminal=true;return false;}return true;}
static bool asc_retain(app_store_controller*s){if(!s->terminal){s->terminal=true;if(s->hooks.retain)s->hooks.retain(s->hooks.context);}return false;}
static void asc_notice(app_store_controller*s,const char*m){snprintf(s->message,sizeof(s->message),"%s",m);s->dirty=true;}
static bool asc_acquire(app_store_controller*s,const char*n,uint32_t api,uint64_t instance,risc_runtime_capability_v1*g){if(!asc_live(s))return false;if(g->api||g->slot||g->generation)return asc_retain(s);*g=(risc_runtime_capability_v1){.struct_size=sizeof(*g)};bool ok=s->runtime->acquire(n,api,instance,g);if(!asc_live(s))return false;if(g->struct_size!=sizeof(*g)||(ok?(!g->api||!g->slot||!g->generation):(g->api||g->slot||g->generation)))return asc_retain(s);return ok;}
static bool asc_release(app_store_controller*s,risc_runtime_capability_v1*g){if(!asc_live(s))return false;if(!g->api){if(g->slot||g->generation)return asc_retain(s);return true;}if(g->struct_size!=sizeof(*g)||!g->slot||!g->generation)return asc_retain(s);bool ok=s->runtime->release(g);if(!asc_live(s))return false;if(!ok||g->struct_size!=sizeof(*g)||g->api||g->slot||g->generation)return asc_retain(s);return true;}
static bool asc_pause(app_store_controller*s){return asc_live(s)&&(!s->hooks.pause||s->hooks.pause(s->hooks.context))&&asc_live(s);}
static bool asc_status(app_store_controller*s){if(!asc_live(s)||!s->service)return false;software_update_status_v1 v={.struct_size=sizeof(v)};bool ok=s->service->status(s->service->context,&v);if(!asc_live(s))return false;if(!ok){s->cleanup_pending=true;asc_notice(s,"Service status unavailable; retry cleanup");return false;}if(v.struct_size!=sizeof(v)||v.state>SOFTWARE_UPDATE_ACTIVATION_UNKNOWN||v.count>SOFTWARE_UPDATE_ROWS_MAX||v.done>v.total)return asc_retain(s);if(v.state==SOFTWARE_UPDATE_RETAINED)return asc_retain(s);if(memcmp(&v,&s->status,sizeof(v)))s->dirty=true;s->status=v;return true;}
static bool asc_row(app_store_controller*s,unsigned index,software_update_row_v1*out){if(!asc_live(s)||!s->service||index>=s->status.count)return false;*out=(software_update_row_v1){.struct_size=sizeof(*out)};bool ok=s->service->get(s->service->context,index,out);if(!asc_live(s))return false;if(!ok)return false;if(out->struct_size!=sizeof(*out)||!memchr(out->id,0,sizeof(out->id))||!memchr(out->version,0,sizeof(out->version))||!memchr(out->installed,0,sizeof(out->installed))||!memchr(out->reason,0,sizeof(out->reason)))return asc_retain(s);return true;}
static bool asc_same_row(const software_update_row_v1*a,const software_update_row_v1*b){return a->availability==b->availability&&a->size==b->size&&!strcmp(a->id,b->id)&&!strcmp(a->version,b->version)&&!strcmp(a->installed,b->installed)&&!strcmp(a->reason,b->reason);}
static bool asc_radio_close(app_store_controller*s){if(!asc_live(s))return false;if(s->wifi&&s->radio_owned){bool ok=s->wifi->disconnect_checked(s->wifi->context);if(!asc_live(s))return false;if(!ok){s->cleanup_pending=true;asc_notice(s,"Radio cleanup unconfirmed");return asc_retain(s);}}if(!asc_release(s,&s->wifi_grant))return false;s->wifi=NULL;s->radio_owned=false;s->connecting=false;return true;}
static bool asc_cancel(app_store_controller*s){if(!asc_pause(s))return false;if(s->restart_pending){asc_notice(s,"Activation requires restart");return false;}bool closed=true;if(s->service){closed=s->service->cancel(s->service->context);if(!asc_live(s))return false;}/* A false cancel retains the live service and blocks every new operation. */if(!closed){s->cleanup_pending=true;asc_notice(s,"Finishing cancellation; retry cleanup");return false;}if(!asc_radio_close(s))return false;s->cleanup_pending=false;s->confirming=false;s->install_after_connect=false;s->network_wait=false;asc_notice(s,"Cancelled; check again when ready");return !s->service||asc_status(s);}
static bool asc_clock(app_store_controller*s,uint64_t*out){if(!asc_live(s))return false;if(!s->clock){if(!asc_acquire(s,RISC_REALTIME_CAPABILITY,1,0,&s->clock_grant))return false;s->clock=s->clock_grant.api;if(!s->clock||s->clock->api_version!=1||s->clock->struct_size<sizeof(*s->clock)||!s->clock->read)return asc_retain(s);}risc_realtime_snapshot_v1 v={.struct_size=sizeof(v)};int rc=s->clock->read(s->clock->context,&v);if(!asc_live(s))return false;if(rc!=RISC_REALTIME_OK&&rc!=RISC_REALTIME_INVALID&&rc!=RISC_REALTIME_IO)return asc_retain(s);if(rc!=RISC_REALTIME_OK)return false;if(v.struct_size!=sizeof(v)||v.validity!=RISC_REALTIME_VALID||v.reserved||v.nanoseconds>=1000000000u||v.nanoseconds%1000u||v.monotonic_before_us>v.monotonic_after_us||v.epoch_seconds<1704067200LL||v.epoch_seconds>4102444799LL)return false;*out=(uint64_t)v.epoch_seconds;return true;}
static bool asc_radio_allowed(app_store_controller*s){risc_runtime_capability_v1 g={0};uint8_t flags=0;if(!asc_acquire(s,RISC_KEY_VALUE_CAPABILITY,1,1,&g))return false;const risc_key_value_v1*k=g.api;if(!k||k->api_version!=1||k->struct_size<sizeof(*k)||!k->get){asc_retain(s);return false;}uint8_t b[4];uint32_t z=0;int rc=k->get(k->context,"quick_radio",b,sizeof(b),&z);if(!asc_live(s))return false;if(rc==RISC_KEY_VALUE_CONTEXT||rc>RISC_KEY_VALUE_OK||rc<RISC_KEY_VALUE_BUSY)return asc_retain(s);bool valid=rc==RISC_KEY_VALUE_NOT_FOUND;if(valid)flags=PORTABLE_RADIO_WIFI;else if(rc==RISC_KEY_VALUE_OK)valid=portable_radio_decode(b,z,&flags);if(!asc_release(s,&g))return false;return valid&&(flags&PORTABLE_RADIO_WIFI);}
static int32_t asc_credentials_get(void*context,const char*k,void*b,uint32_t cap,uint32_t*n){app_store_controller*s=context;if(!asc_live(s)||!s->storage)return RISC_KEY_VALUE_CONTEXT;int rc=s->storage->get(s->storage->context,k,b,cap,n);if(!asc_live(s))return RISC_KEY_VALUE_CONTEXT;if(rc==RISC_KEY_VALUE_CONTEXT||rc>RISC_KEY_VALUE_OK||rc<RISC_KEY_VALUE_BUSY){asc_retain(s);return RISC_KEY_VALUE_CONTEXT;}return rc;}
static int32_t asc_no_write(void*context,const char*k,const void*b,uint32_t n){(void)context;(void)k;(void)b;(void)n;return RISC_KEY_VALUE_CONTEXT;}
/* Explicit action only. No automatic retry or credentials write. */
static bool asc_connect_mode(app_store_controller*s,bool install,bool continuation){if(!asc_pause(s)||!s->service||s->cleanup_pending||s->restart_pending)return false;if(continuation)s->network_wait=true;if(!asc_radio_allowed(s)){if(asc_live(s))asc_notice(s,"Wi-Fi is off or policy unavailable");return false;}if(!continuation&&!asc_cancel(s))return false;if(s->wifi_grant.api)return false;if(!asc_acquire(s,"net.wifi",1,0,&s->wifi_grant)){if(asc_live(s))asc_notice(s,"Wi-Fi unavailable");return false;}s->wifi=s->wifi_grant.api;if(!portable_wifi_saved_network_api_valid(s->wifi))return asc_retain(s);wifi_link_t link=s->wifi->status(s->wifi->context);if(!asc_live(s))return false;if(link!=WIFI_LINK_DOWN){asc_notice(s,"Wi-Fi busy; try later");return asc_radio_close(s)&&false;}
 portable_wifi_credentials c={{0},{0}};risc_key_value_v1 checked={1,sizeof(checked),s,asc_credentials_get,asc_no_write};int loaded=portable_wifi_credentials_load(s->storage?&checked:NULL,&c);if(!asc_live(s)){portable_wifi_credentials_clear(&c);return false;}if(loaded!=PORTABLE_WIFI_CREDENTIALS_LOADED){portable_wifi_credentials_clear(&c);asc_notice(s,"Save a network in Wi-Fi Settings first");return asc_radio_close(s)&&false;}s->radio_owned=true;bool ok=s->wifi->connect(s->wifi->context,c.ssid,c.password);portable_wifi_credentials_clear(&c);if(!asc_live(s))return false;if(!ok){asc_notice(s,"Connection failed; retry Check");return asc_radio_close(s)&&false;}s->connecting=true;s->install_after_connect=install;s->network_continuation=continuation;if(!s->runtime->monotonic_ms(&s->connect_started)||!asc_live(s))return asc_retain(s);asc_notice(s,"Connecting with saved Wi-Fi");return true;}
static bool asc_connect(app_store_controller*s,bool install){return asc_connect_mode(s,install,false);}
static bool asc_init(app_store_controller*s,const risc_runtime_api_v1*rt,app_store_hooks hooks){memset(s,0,sizeof(*s));s->runtime=rt;s->hooks=hooks;s->status.struct_size=sizeof(s->status);if(!asc_live(s))return false;if(rt->api_version!=1||rt->struct_size<RISC_RUNTIME_MONOTONIC_V1_SIZE||!rt->acquire||!rt->release||!rt->monotonic_ms||!rt->yield_ms)return asc_retain(s);if(asc_acquire(s,SOFTWARE_UPDATE_APPS_CAPABILITY,1,0,&s->service_grant)){s->release=s->service=s->service_grant.api;const software_update_v1*u=s->service;if(!u||u->api_version!=1||u->struct_size<sizeof(*u)||!u->refresh||!u->step||!u->status||!u->get||!u->begin||!u->cancel||!u->activate||!u->restart)return asc_retain(s);}if(!asc_live(s))return false;if(asc_acquire(s,RISC_KEY_VALUE_CAPABILITY,1,6,&s->storage_grant)){s->storage=s->storage_grant.api;if(!s->storage||s->storage->api_version!=1||s->storage->struct_size<sizeof(*s->storage)||!s->storage->get)return asc_retain(s);}if(!asc_live(s))return false;s->opened=true;asc_notice(s,s->service?"Check for apps":"App service unavailable");return !s->service||asc_status(s);}
static bool asc_select(app_store_controller*s,unsigned index){software_update_row_v1 row;if(s->connecting||s->cleanup_pending||s->restart_pending||(s->status.state>=SOFTWARE_UPDATE_CATALOG&&s->status.state!=SOFTWARE_UPDATE_LIST&&s->status.state!=SOFTWARE_UPDATE_ERROR)||!asc_row(s,index,&row))return false;s->selected=index;s->selected_row=row;s->confirming=true;asc_notice(s,row.reason);return true;}
static bool asc_confirm(app_store_controller*s){software_update_row_v1 row;if(!s->confirming||!asc_row(s,s->selected,&row))return false;s->confirming=false;if(!asc_same_row(&row,&s->selected_row)){asc_notice(s,"App changed; select and confirm again");return false;}if(row.availability!=SOFTWARE_UPDATE_AVAILABLE)return false;return asc_connect(s,true);}
static bool asc_tick(app_store_controller*s){if(!asc_live(s)||!s->service||s->cleanup_pending||s->restart_pending)return asc_live(s);if(s->connecting){wifi_link_t link=s->wifi->status(s->wifi->context);if(!asc_live(s))return false;uint32_t now=0;if(!s->runtime->monotonic_ms(&now)||!asc_live(s))return asc_retain(s);if(link==WIFI_LINK_UP){wifi_ipv4_v1 ip={0},ap={0};bool ready=s->wifi->addresses(s->wifi->context,&ip,&ap);if(!asc_live(s))return false;if(ready&&(ip.address[0]||ip.address[1]||ip.address[2]||ip.address[3])){s->connecting=false;uint64_t utc=0;bool ok=asc_clock(s,&utc);if(!asc_live(s))return false;if(ok){if(s->network_continuation){ok=s->hooks.network_ready&&s->hooks.network_ready(s->hooks.context,utc);}else if(s->install_after_connect){software_update_row_v1 row;ok=asc_row(s,s->selected,&row)&&asc_same_row(&row,&s->selected_row);if(ok)ok=s->service->begin(s->service->context,s->selected,utc);}else ok=s->service->refresh(s->service->context,utc);}if(!asc_live(s))return false;if(!ok){(void)asc_cancel(s);asc_notice(s,"Check/install unavailable; verify time and retry");}return asc_live(s);}}if(link>WIFI_LINK_UP||link==WIFI_LINK_DOWN||(uint32_t)(now-s->connect_started)>=30000u){if(!asc_radio_close(s))return false;asc_notice(s,"Connection failed or timed out; retry Check");}return true;}
 if(s->hooks.network_needed&&s->hooks.network_needed(s->hooks.context)&&!s->wifi_grant.api&&!s->network_wait){if(!asc_live(s))return false;return asc_connect_mode(s,false,true);}
 if(s->wifi&&s->radio_owned){wifi_link_t link=s->wifi->status(s->wifi->context);if(!asc_live(s))return false;wifi_ipv4_v1 ip={0},ap={0};bool healthy=link==WIFI_LINK_UP;if(healthy){healthy=s->wifi->addresses(s->wifi->context,&ip,&ap);if(!asc_live(s))return false;healthy=healthy&&(ip.address[0]||ip.address[1]||ip.address[2]||ip.address[3]);}if(!healthy){bool ok=asc_cancel(s);if(!asc_live(s))return false;asc_notice(s,"Connection lost; retry Check");return ok;}}
 (void)s->service->step(s->service->context);if(!asc_live(s)||!asc_status(s))return false;if(s->status.state==SOFTWARE_UPDATE_LIST||s->status.state==SOFTWARE_UPDATE_ERROR){if(!asc_radio_close(s))return false;if(s->status.state==SOFTWARE_UPDATE_ERROR)asc_notice(s,"Update failed; current install kept");}
 if(s->status.state==SOFTWARE_UPDATE_READY){if(!asc_pause(s)||!asc_radio_close(s))return false;bool ok=s->service->activate(s->service->context);if(!asc_live(s))return false;if(!ok){bool known=asc_status(s);if(!asc_live(s))return false;if(!known||s->status.state==SOFTWARE_UPDATE_ACTIVATION_UNKNOWN){s->restart_pending=true;asc_notice(s,"Activation uncertain; restart required");}else asc_notice(s,"Activation failed; retry Check");}else{s->restart_pending=true;asc_notice(s,"Update activated; restart required");}s->confirming=false;}return asc_live(s);}
static bool asc_restart(app_store_controller*s){if(!asc_live(s)||!s->restart_pending)return false;bool ok=s->service->restart(s->service->context);if(!asc_live(s))return false;if(!ok)asc_notice(s,"Restart not accepted; retry Restart");return ok;}
static bool asc_close(app_store_controller*s){if(!asc_cancel(s))return false;if(!asc_release(s,&s->clock_grant)||!asc_release(s,&s->storage_grant)||!asc_release(s,&s->service_grant))return false;s->service=s->release=NULL;s->storage=NULL;s->clock=NULL;s->opened=false;return true;}
#endif
